<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> filters</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">List</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">Func</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#C678DD;">int</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">bool</span><span style="color:#ABB2BF;">&gt;&gt;();</span></span>
