<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">Where</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">p</span><span style="color:#ABB2BF;"> =&gt; </span><span style="color:#E5C07B;">p</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">IsActive</span><span style="color:#56B6C2;"> &amp;&amp;</span><span style="color:#E5C07B;"> p</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Price</span><span style="color:#56B6C2;"> &gt;</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">)</span></span>
